from pathlib import Path
import re,json,base64,mimetypes
root=Path(__file__).resolve().parents[1];out=root.parent/'review';out.mkdir(exist_ok=True)
pages={f.name:f.read_text() for f in root.glob('*.html')};assets={}
css=(root/'assets/site.css').read_text();js=(root/'assets/site.js').read_text()
for name,s in pages.items():
 s=re.sub(r'\s(?:srcset|sizes)="[^"]*"','',s)
 s=s.replace('<link rel="stylesheet" href="/assets/site.css">','<style>'+css+'</style>').replace('<script src="/assets/site.js" defer></script>','')
 s=s.replace('<head>','<head><meta name="robots" content="noindex,nofollow">')
 s=s.replace('</body>','<script>window.TECH_TAMER_PREVIEW=true;window.TECH_TAMER_QUERY=__QUERY__;'+js+'</script></body>')
 for src in re.findall(r'(?:src|href)="(/assets/[^"]+)"',s):
  p=root/src.lstrip('/')
  if p.is_file() and p.suffix in ['.webp','.png','.jpg','.svg']:assets[src]='data:'+mimetypes.guess_type(p.name)[0]+';base64,'+base64.b64encode(p.read_bytes()).decode()
 pages[name]=s
shell='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tech Tamer — Improvements Preview</title><style>*{box-sizing:border-box}body{margin:0;background:#e5e9f1;font-family:Arial,sans-serif}.bar{background:#172440;color:white;padding:12px 18px;display:flex;gap:14px;align-items:center;flex-wrap:wrap}.bar strong{font-size:15px}.bar span{font-size:12px;color:#d2dced}.bar select,.bar button{font:inherit;padding:8px;background:white;border:1px solid #8896ae;color:#23335c;border-radius:4px}.bar button.active{background:#c9edff}.notice{font-size:12px;padding:8px 18px;background:#fff6d8;color:#55431b}iframe{width:100%;height:calc(100dvh - 110px);display:block;border:0;background:white;margin:auto}iframe.phone{width:390px;max-width:100%}@media(max-width:620px){.bar{gap:8px;padding:9px 12px}.bar span{display:none}.bar select{max-width:140px}.bar button{font-size:12px}.notice{font-size:11px}iframe{height:calc(100dvh - 130px)}}</style></head><body><div class="bar"><strong>The Tech Tamer</strong><span>Review draft · Not deployed</span><select id="page" aria-label="Preview page"><option value="index.html">Home</option><option value="services.html">Tech Help</option><option value="business.html">For Business</option><option value="digital-kits.html">Digital Kits</option><option value="rates.html">Rates & FAQ</option><option value="about.html">About Josh</option><option value="contact.html">Contact</option><option value="404.html">404 page</option></select><button id="desktop" class="active">Desktop</button><button id="phone">Phone</button></div><div class="notice">Review carousel, visit details and the new contact form. Form submissions are demonstrations only; nothing is sent. Live form connection is pending.</div><iframe id="site" title="Unpublished website preview"></iframe><script>const pages=__PAGES__,assets=__ASSETS__,frame=document.getElementById('site'),picker=document.getElementById('page');function show(){const route=location.hash.slice(1)||'index.html';const parts=route.split('?');const key=pages[parts[0]]?parts[0]:'index.html';picker.value=key;let html=pages[key].replace('__QUERY__',JSON.stringify(parts[1]?'?'+parts[1]:''));for(const [path,data]of Object.entries(assets))html=html.split('"'+path+'"').join('"'+data+'"');frame.srcdoc=html}frame.addEventListener('load',()=>frame.contentDocument.addEventListener('click',e=>{const a=e.target.closest('a');if(!a)return;const href=a.getAttribute('href')||'';const route=href.replace(/^\\//,'');if(pages[route.split('?')[0]]){e.preventDefault();if(location.hash.slice(1)===route)show();else location.hash=route}}));picker.addEventListener('change',()=>location.hash=picker.value);window.addEventListener('hashchange',show);for(const mode of ['desktop','phone'])document.getElementById(mode).addEventListener('click',()=>{frame.classList.toggle('phone',mode==='phone');for(const m of ['desktop','phone'])document.getElementById(m).classList.toggle('active',mode===m)});show();</script></body></html>'''
shell=shell.replace('__PAGES__',json.dumps(pages).replace('</','<\\/')).replace('__ASSETS__',json.dumps(assets))
p=out/'tech-tamer-improvements-preview.html';p.write_text(shell);print(p,p.stat().st_size)
